    def __init__(self):
        self.s = []
    def push(self, x):
        cur = x if not self.s else min(x, self.s[-1][1])
        self.s.append((x, cur))
    def pop(self):
        self.s.pop()
    def top(self):
        return self.s[-1][0]
    def getMin(self):
        return self.s[-1][1]


