import sys

class MinStack:
    def __init__(self):
        self.s = []
        self.min_val = 0
    def push(self, x):
        if not self.s:
            self.min_val = x
            self.s.append(0)
        else:
            diff = x - self.min_val
            self.s.append(diff)
            if diff < 0:
                self.min_val = x
    def pop(self):
        diff = self.s.pop()
        if diff < 0:
            self.min_val = self.min_val - diff
    def top(self):
        diff = self.s[-1]
        return self.min_val if diff < 0 else self.min_val + diff
    def getMin(self):
        return self.min_val


